/**
 * Test guest registration with session creation and token generation.
 *
 * Validates the complete guest registration workflow including device fingerprint identification, session record creation, and JWT token issuance. Ensures that all required data relationships are properly established and that session context information is correctly captured.
 *
 * The test verifies that guest registration creates both guest account and session records with proper foreign key relationships, generates valid access and refresh tokens, and captures session metadata including IP address, entry URL, and referrer information.
 *
 * 1. Generate random device fingerprint and session context data.
 * 2. Register guest account using device fingerprint.
 * 3. Verify guest account record contains correct device_fingerprint.
 * 4. Verify session record exists with proper foreign key relationship.
 * 5. Validate JWT tokens are present and properly formatted.
 * 6. Verify session expiration timestamps are set correctly.
 * 7. Validate session context fields (ip, href, referrer) are captured.
 */
export async function test_api_guest_join_session_creation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Prepare guest registration data with randomized values
  const guestConnection: api.IConnection = { host: connection.host };
  const output: IHrmGuest.IAuthorized = await authorize_guest_join(
    guestConnection,
    {
      body: {
        device_fingerprint: RandomGenerator.alphaNumeric(32),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
        ip: typia.random<string & tags.Format<"ipv4">>(),
      } satisfies IHrmGuest.IJoin,
    },
  );
  // 2. Validate response structure
  typia.assert(output);
  // 3. Verify guest account fields
  TestValidator.equals("guest ID is UUID", output.id.length, 36);
  TestValidator.predicate(
    "created_at is valid date-time",
    output.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at is valid date-time",
    output.updated_at.length > 0,
  );
  // 4. Verify authorization tokens
  TestValidator.predicate(
    "access token exists",
    output.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token exists",
    output.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "expired_at is valid date-time",
    output.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refreshable_until is valid date-time",
    output.token.refreshable_until.length > 0,
  );
  // 5. Verify session data exists
  TestValidator.predicate("sessions array exists", output.sessions.length > 0);
  const session = output.sessions[0];
  typia.assert(session);
  // 6. Verify session record fields
  TestValidator.equals("session ID is UUID", session.id.length, 36);
  TestValidator.predicate("session IP exists", session.ip.length > 0);
  TestValidator.predicate("session href exists", session.href.length > 0);
  TestValidator.predicate(
    "session created_at is valid",
    session.created_at.length > 0,
  );
  TestValidator.predicate(
    "session expired_at is valid",
    session.expired_at.length > 0,
  );
  // Referrer can be null per DTO definition, so validate accordingly
  TestValidator.predicate(
    "session referrer is valid (null or string)",
    session.referrer === null || session.referrer.length > 0,
  );
  // 7. Verify guest relationship in session
  TestValidator.equals("guest ID matches", session.guest.id, output.id);
  TestValidator.equals(
    "guest device fingerprint matches",
    session.guest.device_fingerprint,
    output.device_fingerprint,
  );
  TestValidator.predicate(
    "guest created_at is valid",
    session.guest.created_at.length > 0,
  );
  TestValidator.predicate(
    "sessions_count is at least 1",
    session.guest.sessions_count >= 1,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IHrmGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmGuest";
import type { IHrmGuestSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmGuestSession";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test duplicate device fingerprint handling during guest registration.
 *
 * Validates that when the same device_fingerprint is submitted twice, the system maintains data integrity by either returning the existing guest record with new session tokens or rejecting the duplicate registration. This is critical for security and preventing duplicate guest identities in the system.
 *
 * The test covers two scenarios:
 * 1. First guest registration with unique fingerprint - should succeed
 * 2. Second registration attempt with identical fingerprint - should handle consistently (return existing or reject)
 *
 * 1. Create first guest with random device fingerprint and session context.
 * 2. Validate first join response contains valid UUID, JWT tokens, and session information.
 * 3. Attempt second guest join with the same device fingerprint.
 * 4. Verify system behavior: either returns existing guest with new tokens OR throws appropriate error.
 * 5. Ensure no duplicate guest records are created for the same fingerprint.
 * 6. Validate token generation works correctly in both scenarios.
 */
export async function test_api_guest_join_duplicate_fingerprint(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create first guest with unique device fingerprint
  const guestConnection1: api.IConnection = { host: connection.host };
  const deviceFingerprint: string = RandomGenerator.alphaNumeric(32);
  const firstGuest: IHrmGuest.IAuthorized = await authorize_guest_join(
    guestConnection1,
    {
      body: {
        device_fingerprint: deviceFingerprint,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
        ip: typia.random<string & tags.Format<"ipv4">>(),
      } satisfies IHrmGuest.IJoin,
    },
  );
  typia.assert(firstGuest);
  // 2. Validate first guest registration response
  TestValidator.predicate(
    "first guest has valid UUID",
    /^[0-9a-f-]{36}$/i.test(firstGuest.id),
  );
  TestValidator.predicate(
    "first guest has access token",
    firstGuest.token.access.length > 0,
  );
  TestValidator.predicate(
    "first guest has refresh token",
    firstGuest.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "first guest has valid device fingerprint",
    firstGuest.device_fingerprint === deviceFingerprint,
  );
  TestValidator.predicate(
    "first guest has sessions",
    firstGuest.sessions.length > 0,
  );
  // 3. Attempt second guest join with SAME device fingerprint
  const guestConnection2: api.IConnection = { host: connection.host };
  try {
    const secondGuest: IHrmGuest.IAuthorized = await authorize_guest_join(
      guestConnection2,
      {
        body: {
          device_fingerprint: deviceFingerprint, // Same fingerprint as first guest
          href: typia.random<string & tags.Format<"uri">>(),
          referrer: typia.random<string & tags.Format<"uri">>(),
          ip: typia.random<string & tags.Format<"ipv4">>(),
        } satisfies IHrmGuest.IJoin,
      },
    );
    typia.assert(secondGuest);
    // 4a. If system returns existing guest (duplicate fingerprint policy: return existing)
    // Validate that the returned guest ID matches the first guest
    TestValidator.equals(
      "duplicate fingerprint returns same guest",
      secondGuest.id,
      firstGuest.id,
    );
    TestValidator.predicate(
      "second guest has new access token",
      secondGuest.token.access !== firstGuest.token.access,
    );
    TestValidator.predicate(
      "second guest has valid device fingerprint",
      secondGuest.device_fingerprint === deviceFingerprint,
    );
    // Verify sessions count - either same or increased (new session may or may not be created)
    TestValidator.predicate(
      "sessions exist for duplicate guest",
      secondGuest.sessions.length > 0,
    );
  } catch (error) {
    // 4b. If system rejects duplicate fingerprint (duplicate fingerprint policy: reject)
    if (typia.is<api.HttpError>(error)) {
      const httpError: api.HttpError = error;
      // Validate appropriate error status (409 Conflict or 400 Bad Request)
      TestValidator.predicate(
        "duplicate fingerprint rejected with appropriate status",
        httpError.status === 409 || httpError.status === 400,
      );
      // Validate error message mentions duplicate or fingerprint
      const errorMessage: string =
        typeof httpError.toJSON().message === "string"
          ? httpError.toJSON().message as string
          : JSON.stringify(httpError.toJSON().message);
      TestValidator.predicate(
        "error message mentions duplicate or fingerprint",
        errorMessage.toLowerCase().includes("duplicate") ||
          errorMessage.toLowerCase().includes("fingerprint") ||
          errorMessage.toLowerCase().includes("already"),
      );
    } else {
      throw error;
    }
  }
  // 5. Final validation: system correctly handles duplicate fingerprints
  // Either returns existing guest or rejects - both are valid behaviors
  // The key is that duplicate guest records are never created
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IHrmGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmGuest";
import type { IHrmGuestSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IHrmGuestSession";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_guest_join } from "../../../authorize/authorize_guest_join";
import { authorize_guest_refresh } from "../../../authorize/authorize_guest_refresh";

/**
 * Test successful guest session token refresh with valid refresh token.
 *
 * Validates the complete guest token refresh workflow including initial guest registration, token renewal, and single-use refresh token enforcement. Ensures that the system correctly generates new access and refresh tokens while invalidating the old refresh token to prevent replay attacks.
 *
 * The test verifies the core token renewal mechanism and validates that:
 * 1. Initial guest registration creates valid tokens
 * 2. Refresh request with valid token succeeds and returns new tokens
 * 3. Token expiration timestamps are properly updated
 * 4. Old refresh token cannot be reused (single-use enforcement)
 * 5. Guest account remains accessible with new tokens
 *
 * 1. Create guest account via join with device fingerprint and session context.
 * 2. Capture the initial refresh token from the authorization response.
 * 3. Perform first refresh request with valid refresh token.
 * 4. Validate response contains new access and refresh tokens with updated expiration.
 * 5. Verify old refresh token is invalid and cannot be reused.
 * 6. Confirm guest account remains accessible with new tokens.
 */
export async function test_api_guest_refresh_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create guest account via join
  const guestConnection: api.IConnection = { host: connection.host };
  const initialAuth: IHrmGuest.IAuthorized = await authorize_guest_join(
    guestConnection,
    {
      body: {
        device_fingerprint: RandomGenerator.alphaNumeric(32),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
        ip: typia.random<string & tags.Format<"ipv4">>(),
      } satisfies IHrmGuest.IJoin,
    },
  );
  typia.assert(initialAuth);
  // Store the initial refresh token
  const oldRefreshToken: string = initialAuth.token.refresh;
  // 2. Perform first refresh request with valid refresh token
  const refreshAuth: IHrmGuest.IAuthorized = await authorize_guest_refresh(
    guestConnection,
    {
      body: {
        refreshToken: oldRefreshToken,
      } satisfies IHrmGuest.IRefresh,
    },
  );
  typia.assert(refreshAuth);
  // 3. Verify guest id remains unchanged after refresh
  TestValidator.equals("guest id unchanged", refreshAuth.id, initialAuth.id);
  // 4. Verify new tokens are different from old tokens (token rotation)
  TestValidator.notEquals(
    "new access token differs",
    refreshAuth.token.access,
    initialAuth.token.access,
  );
  TestValidator.notEquals(
    "new refresh token differs",
    refreshAuth.token.refresh,
    initialAuth.token.refresh,
  );
  // 5. Verify old refresh token is invalid and cannot be reused (single-use enforcement)
  await TestValidator.error("old refresh token invalid", async () => {
    await authorize_guest_refresh(guestConnection, {
      body: {
        refreshToken: oldRefreshToken,
      } satisfies IHrmGuest.IRefresh,
    });
  });
  // 6. Confirm guest account remains accessible with new tokens
  TestValidator.equals(
    "authorization uses new token",
    guestConnection.headers?.Authorization,
    refreshAuth.token.access,
  );
}

