  });
  typia.assert(memberAuth);
  // Validate member registration
  TestValidator.predicate("member registered", memberAuth.id !== undefined);
  TestValidator.predicate(
    "email verified initially false",
    memberAuth.email_verified === false,
  );
  // 2. Get organization from member auth response
  // Note: After join, organizations array should be empty since member hasn't joined any organization yet
  // We need to use the organization context from the login response or assume an organization exists
  // For this test, we'll use a UUID for organization_id - in real scenario, this would come from organization creation/join
  const organizationId =
    memberAuth.organizations?.[0]?.id ??
    typia.random<string & tags.Format<"uuid">>();
  // 3. Test is_builtin=false filter - should return only custom roles
  const customRolesResult =
    await api.functional.hrm.member.organizations.roles.index(
      memberConnection,
      {
        organizationId,
        body: {
          organization_id: organizationId,
          is_builtin: false,
        } satisfies IHrmRole.IRequest,
      },
    );
  typia.assert(customRolesResult);
  // Validate that all returned roles are custom (is_builtin = false)
  for (const role of customRolesResult.data) {
    TestValidator.predicate("role is custom", role.is_builtin === false);
  }
  // 4. Test is_builtin=true filter - should return only built-in roles
  const builtinRolesResult =
    await api.functional.hrm.member.organizations.roles.index(
      memberConnection,
      {
        organizationId,
        body: {
          organization_id: organizationId,
          is_builtin: true,
        } satisfies IHrmRole.IRequest,
      },
