  for (const role of builtinRolesResult.data) {
    TestValidator.predicate("role is built-in", role.is_builtin === true);
  }
  // 5. Test no filter - should return all roles (both built-in and custom)
  const allRolesResult =
    await api.functional.hrm.member.organizations.roles.index(
      memberConnection,
      {
        organizationId,
        body: {
          organization_id: organizationId,
        } satisfies IHrmRole.IRequest,
      },
    );
  typia.assert(allRolesResult);
  // Validate total count matches sum of filtered results
  TestValidator.equals(
    "total roles count",
    allRolesResult.data.length,
    customRolesResult.data.length + builtinRolesResult.data.length,
  );
  // 6. Verify role uniqueness across all queries
  const allRoleIds = new Set(allRolesResult.data.map((r) => r.id));
  TestValidator.predicate(
    "all roles have unique IDs",
    allRoleIds.size === allRolesResult.data.length,
  );
  // 7. Validate pagination metadata
  TestValidator.predicate(
    "pagination current >= 1",
    allRolesResult.pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination limit >= 0",
    allRolesResult.pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination records >= 0",
    allRolesResult.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages >= 0",
    allRolesResult.pagination.pages >= 0,
  );
}

