    "pending",
    "accepted",
    "expired",
    "cancelled",
  ];
  for (const status of statuses) {
    const filtered = await api.functional.hrm.member.invitations.index(
      memberConnection,
      {
        body: {
          status,
          page: 1,
          limit: 100,
        } satisfies IHrmEmployeeInvitation.IRequest,
      },
