          start_date: new Date(Date.now() + 86400000).toISOString(),
          pay_rate: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
          pay_period: RandomGenerator.pick([
            "hourly",
            "daily",
            "weekly",
            "monthly",
          ]),
        } satisfies IHrmContract.ICreate,
      },
