        snapshot.employee !== undefined &&
        snapshot.employee.id !== undefined &&
        snapshot.start_date !== undefined &&
        snapshot.pay_rate !== undefined &&
        snapshot.pay_period !== undefined &&
        snapshot.created_at !== undefined
      );
    }),
  );
