 *
 * The test verifies filtering by single status values, pagination with status filters, and validates that all returned projects belong to the authenticated member's organization. Empty result sets are also tested to ensure proper handling when no projects match the filter criteria.
 *
 * 1. Member registers and authenticates with the system.
 * 2. Filter projects by single status (active) and verify results.
 * 3. Filter projects by single status (archived) and verify results.
 * 4. Filter projects by single status (completed) and verify results.
 * 5. Test status filtering with pagination parameters.
 * 6. Test empty result set when no projects match the status filter.
 * 7. Verify organization context enforcement on all filtered results.
 */
export async function test_api_project_list_filter_by_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Member registration and authentication
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IHrmMember.IJoin,
  });
  typia.assert(memberAuth);
  // 2. Test filtering by single status - active
  const activeFilter: IHrmProject.IRequest = {
    status: "active",
    page: 1,
    limit: 20,
  } satisfies IHrmProject.IRequest;
  const activeProjects = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: activeFilter,
    },
  );
  typia.assert(activeProjects);
  // Validate all returned projects have active status
  for (const project of activeProjects.data) {
    TestValidator.equals(
      "all projects should have active status",
      project.status,
      "active",
    );
  }
  // 3. Test filtering by single status - archived
  const archivedFilter: IHrmProject.IRequest = {
    status: "archived",
    page: 1,
    limit: 20,
  } satisfies IHrmProject.IRequest;
  const archivedProjects = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: archivedFilter,
    },
  );
  typia.assert(archivedProjects);
  // Validate all returned projects have archived status
  for (const project of archivedProjects.data) {
    TestValidator.equals(
      "all projects should have archived status",
      project.status,
      "archived",
    );
  }
  // 4. Test filtering by single status - completed
  const completedFilter: IHrmProject.IRequest = {
    status: "completed",
    page: 1,
    limit: 20,
  } satisfies IHrmProject.IRequest;
  const completedProjects = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: completedFilter,
    },
  );
  typia.assert(completedProjects);
  // Validate all returned projects have completed status
  for (const project of completedProjects.data) {
    TestValidator.equals(
      "all projects should have completed status",
      project.status,
      "completed",
    );
  }
  // 5. Test filtering without status filter (should return all projects)
  const allProjectsFilter: IHrmProject.IRequest = {
    page: 1,
    limit: 20,
  } satisfies IHrmProject.IRequest;
  const allProjects = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: allProjectsFilter,
    },
  );
  typia.assert(allProjects);
  // Validate pagination metadata is present and valid
  TestValidator.predicate(
    "pagination records should be non-negative",
    allProjects.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages should be non-negative",
    allProjects.pagination.pages >= 0,
  );
  // 6. Test pagination with status filter
  const paginatedFilter: IHrmProject.IRequest = {
    status: "active",
    page: 1,
    limit: 5,
  } satisfies IHrmProject.IRequest;
  const paginatedResult = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: paginatedFilter,
    },
  );
  typia.assert(paginatedResult);
  // Validate limit is respected
  TestValidator.predicate(
    "page should not exceed limit",
    paginatedResult.data.length <= paginatedResult.pagination.limit,
  );
  // 7. Test empty result set scenario (filter by status with no matching projects)
  // This validates the API handles empty results correctly
  const emptyResultFilter: IHrmProject.IRequest = {
    status: "active",
    page: 1,
    limit: 20,
    search: typia.random<string & tags.Format<"uuid">>(), // Use random UUID unlikely to match any project
  } satisfies IHrmProject.IRequest;
  const emptyResult = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: emptyResultFilter,
    },
  );
  typia.assert(emptyResult);
  // Validate empty result handling
  TestValidator.equals(
    "empty result should have zero records",
    emptyResult.pagination.records,
    0,
  );
  TestValidator.equals(
    "empty result should have empty data array",
    emptyResult.data.length,
    0,
  );
  // 8. Verify organization context - all projects should belong to same organization
  const orgId = memberAuth.organizations?.[0]?.id;
  if (orgId !== undefined && orgId !== null) {
    // Validate organization context for active projects
    for (const project of activeProjects.data) {
      TestValidator.equals(
        "project organization should match member organization",
        project.organization.id,
        orgId,
      );
    }
    // Validate organization context for archived projects
    for (const project of archivedProjects.data) {
      TestValidator.equals(
        "project organization should match member organization",
        project.organization.id,
        orgId,
      );
    }
    // Validate organization context for completed projects
    for (const project of completedProjects.data) {
      TestValidator.equals(
        "project organization should match member organization",
        project.organization.id,
        orgId,
      );
    }
  }
