/**
 * Test text search functionality on project list endpoint.
 *
 * Validates the trigram-based partial text matching capability for project discovery through name and description fields. The test authenticates as a member and performs various search scenarios to ensure the search functionality works correctly with partial matching, case-insensitivity, and combined filters.
 *
 * This test covers the following search behaviors:
 * - Partial text matching on project name and description
 * - Case-insensitive search operations
 * - Search combined with status filtering
 * - Empty search results with valid pagination structure
 * - Organization context isolation enforcement
 *
 * 1. Member authenticates via join endpoint with randomized credentials.
 * 2. Test basic text search returns projects containing the search term.
 * 3. Test case-insensitive matching (e.g., "alpha" finds "Alpha").
 * 4. Test search combined with status filter (active projects only).
 * 5. Test non-matching search returns empty results with valid pagination.
 * 6. Test description search functionality.
 * 7. Verify pagination structure is maintained across all search scenarios.
 */
export async function test_api_project_list_text_search(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as member
  const memberConnection: api.IConnection = { host: connection.host };
  const auth = await api.functional.hrm.auth.member.join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IHrmMember.IJoin,
  });
  typia.assert(auth);
  // 2. Test basic text search - partial matching on name
  const searchTerm = RandomGenerator.alphabets(5);
  const searchResult = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: {
        search: searchTerm,
        limit: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
        >(),
        page: 1,
      } satisfies IHrmProject.IRequest,
    },
  );
  typia.assert(searchResult);
  TestValidator.predicate(
    "search returns valid pagination structure",
    searchResult.pagination.current >= 1 &&
      searchResult.pagination.limit >= 1 &&
      searchResult.pagination.records >= 0,
  );
  // 3. Test case-insensitive search
  const lowerCaseSearch = RandomGenerator.alphabets(4).toLowerCase();
  const caseInsensitiveResult = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: {
        search: lowerCaseSearch,
        limit: 100,
        page: 1,
      } satisfies IHrmProject.IRequest,
    },
  );
  typia.assert(caseInsensitiveResult);
  TestValidator.predicate(
    "case-insensitive search returns valid results",
    caseInsensitiveResult.data.every(
      (p) =>
        typeof p.id === "string" &&
        typeof p.name === "string" &&
        typeof p.status === "string",
    ),
  );
  // 4. Test search combined with status filter
  const statusFilteredResult = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: {
        search: RandomGenerator.alphabets(3),
        status: "active",
        limit: 50,
        page: 1,
      } satisfies IHrmProject.IRequest,
    },
  );
  typia.assert(statusFilteredResult);
  TestValidator.predicate(
    "status-filtered search returns only active projects",
    statusFilteredResult.data.every((p) => p.status === "active"),
  );
  // 5. Test non-matching search returns empty results with valid pagination
  const noMatchResult = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: {
        search: "ZZZZ_NONEXISTENT_PROJECT_XXX",
        limit: 100,
        page: 1,
      } satisfies IHrmProject.IRequest,
    },
  );
  typia.assert(noMatchResult);
  TestValidator.equals(
    "non-matching search returns empty data array",
    noMatchResult.data.length,
    0,
  );
  TestValidator.predicate(
    "pagination structure is valid for empty results",
    noMatchResult.pagination.current === 1 &&
      noMatchResult.pagination.limit === 100 &&
      noMatchResult.pagination.records === 0 &&
      noMatchResult.pagination.pages === 0,
  );
  // 6. Test search with different pagination parameters
  const paginatedSearch = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: {
        search: RandomGenerator.alphabets(4),
        page: 2,
        limit: 20,
      } satisfies IHrmProject.IRequest,
    },
  );
  typia.assert(paginatedSearch);
  TestValidator.equals(
    "page 2 search returns correct page number",
    paginatedSearch.pagination.current,
    2,
  );
  TestValidator.equals(
    "page 2 search respects limit parameter",
    paginatedSearch.pagination.limit,
    20,
  );
  // 7. Test search with date range filters
  const dateFilteredResult = await api.functional.hrm.member.projects.index(
    memberConnection,
    {
      body: {
        search: RandomGenerator.alphabets(3),
        start_date_from: new Date(Date.now() - 86400000 * 30).toISOString(),
        end_date_to: new Date().toISOString(),
        limit: 100,
        page: 1,
      } satisfies IHrmProject.IRequest,
    },
  );
  typia.assert(dateFilteredResult);
  TestValidator.predicate(
    "date-filtered search returns valid project summaries",
    dateFilteredResult.data.every(
