/**
 * Test employee timelog list retrieval with date range filtering.
 *
 * Validates that an authenticated employee can retrieve their own timelog records with flexible filtering options including date ranges, pagination, and billable status. The test verifies the response structure includes proper pagination metadata and aggregated time report summaries.
 *
 * Special attention is given to verifying that date range filtering correctly returns only timelogs within the specified period, and that the response includes proper aggregation of time metrics.
 *
 * 1. Create and authenticate a new member account.
 * 2. Retrieve timelog list with date range filtering (past 30 days).
 * 3. Validate pagination metadata is correct.
 * 4. Validate aggregated time report structure and metrics.
 * 5. Test with future date range to verify empty results handling.
 */
export async function test_api_timelog_list_employee_own_records(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create and authenticate member
  const memberConnection: api.IConnection = { host: connection.host };
  const auth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IHrmMember.IJoin,
  });
  typia.assert(auth);
  TestValidator.predicate("member authenticated", !!auth.token.access);
  // 2. Retrieve timelog list with date range filtering (past 30 days)
  const startDate = new Date();
  startDate.setDate(startDate.getDate() - 30);
  const endDate = new Date();
  const timelogList = await api.functional.hrm.member.timelogs.index(
    memberConnection,
    {
      body: {
        start_date: startDate.toISOString(),
        end_date: endDate.toISOString(),
        page: 1,
        limit: 50,
      } satisfies IHrmTimelog.IRequest,
    },
  );
  typia.assert(timelogList);
  // 3. Validate pagination metadata
  TestValidator.equals(
    "pagination current page",
    timelogList.pagination.current,
    1,
  );
  TestValidator.predicate(
    "pagination limit positive",
    timelogList.pagination.limit > 0,
  );
  TestValidator.predicate(
    "pagination records non-negative",
    timelogList.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages non-negative",
    timelogList.pagination.pages >= 0,
  );
  // 4. Validate aggregated time report structure
  for (const report of timelogList.data) {
    typia.assert(report);
    TestValidator.predicate("report has total hours", report.total_hours >= 0);
    TestValidator.predicate(
      "report has total billable hours",
      report.total_billable_hours >= 0,
    );
    TestValidator.predicate(
      "report has total non-billable hours",
      report.total_non_billable_hours >= 0,
    );
    TestValidator.predicate(
      "report has total entries",
      report.total_entries >= 0,
    );
    // Validate items array exists
    TestValidator.predicate(
      "report has items array",
      Array.isArray(report.items),
    );
    // Validate each item in the array
    for (const item of report.items) {
      typia.assert(item);
      TestValidator.predicate("item has total hours", item.total_hours >= 0);
      TestValidator.predicate(
        "item has total entries",
        item.total_entries >= 0,
      );
    }
  }
  // 5. Test with future date range (should return valid response with no data)
  const futureStartDate = new Date();
  futureStartDate.setDate(futureStartDate.getDate() + 30);
  const futureEndDate = new Date();
  futureEndDate.setDate(futureEndDate.getDate() + 60);
  const futureTimelogList = await api.functional.hrm.member.timelogs.index(
    memberConnection,
    {
      body: {
        start_date: futureStartDate.toISOString(),
        end_date: futureEndDate.toISOString(),
      } satisfies IHrmTimelog.IRequest,
    },
  );
  typia.assert(futureTimelogList);
  // Future date range should return valid response with pagination
  TestValidator.predicate(
    "future range has valid pagination",
    futureTimelogList.pagination.records >= 0,
  );
}

