      body: {
        email: typia.random<string & tags.Format<"email">>(),
        role_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IHrmEmployeeInvitation.ICreate,
    });
  typia.assert(employee2Invitation);
  // 5. Second employee accepts invitation
