      invitationId: employee2Invitation.id,
      body: {
        token: employee2Invitation.token,
      } satisfies IHrmEmployeeInvitation.IAccept,
    });
  typia.assert(employee2InvitationAccepted);
  // 6. Create a timesheet owned by the first employee
