    cursor: null,
  } satisfies IHrmTimelog.ISummary;
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data: [reportSummary],
  } satisfies IPageIHrmTimelog.ISummary;
}

