    ...(props.body.email && {
      email: {
        contains: props.body.email,
        mode: "insensitive",
      },
    }),
    ...(props.body.status && {
      AND:
        props.body.status === "pending"
          ? [{ used_at: null }, { expires_at: { gt: new Date() } }]
          : props.body.status === "used"
