      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data: await ArrayUtil.asyncMap(
      records,
      HrmMemberEmailVerificationAtSummaryTransformer.transform,
    ),
  } satisfies IPageIHrmMemberEmailVerification.ISummary;
}

