import { IPageIHrmEmployeeInvitation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIHrmEmployeeInvitation";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
