import { getHrmMemberMemberSessionsSessionId } from "../../../../../providers/getHrmMemberMemberSessionsSessionId";
import { patchHrmMemberMemberSessions } from "../../../../../providers/patchHrmMemberMemberSessions";

@Controller("/hrm/member/member/sessions")
export class HrmMemberMemberSessionsController {
  /**
   * Retrieve a paginated list of member sessions with optional filtering criteria.
   *
   * This endpoint allows authenticated members to view their session history, including active and expired sessions. Sessions are created upon login and tracked as an audit trail for security purposes. Members can filter sessions by date range, expiration status, and IP address to identify suspicious activity or manage their active sessions.
   *
   * ## Session Visibility
   *
   * Members can only view their own sessions. The system enforces strict data isolation so that each member sees only sessions belonging to their account. Session details include connection metadata such as IP address, referrer URL, and timestamps for security auditing.
   *
   * ## Filtering and Pagination
   *
   * The request body supports filtering by creation date range, expiration status, and IP address. Results are returned with cursor-based pagination to handle large session histories efficiently. Sorting is available by creation date in ascending or descending order.
   *
   * @param connection
   * @param body Search criteria for filtering member sessions including date range, expiration status, IP address, and pagination parameters.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_member_sessions table filtered by hrm_member_id from authenticated session context.
   *
   * Apply search filters from request body:
   * - date_range: Filter sessions by created_at within specified start/end timestamps
   * - is_active: Filter by expiration status (expired_at > current_time)
   * - ip_address: Filter by exact IP address match
   *
   * Implement cursor-based pagination using created_at and id as cursor keys.
   *
   * Sort results by created_at descending by default (newest first).
   *
   * Return IHrmMemberSession.ISummary for each session, excluding sensitive token data (access_token, refresh_token should not be exposed).
   *
   * Enforce authorization: only return sessions where hrm_member_id matches the authenticated member.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IHrmMemberSession.IRequest,
  ): Promise<IPageIHrmMemberSession.ISummary> {
    try {
      return await patchHrmMemberMemberSessions({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed information about a specific member session.
   *
   * This endpoint returns session metadata including creation timestamp, expiration time, IP address, and page context information. Sensitive authentication tokens (access_token, refresh_token) are excluded from the response for security reasons.
   *
   * ## Security and Access Control
   *
   * Only the session owner (the member who created the session) can retrieve session details. The system validates that the requested session belongs to the currently authenticated member before returning data. Cross-session access is strictly prohibited.
   *
   * ## Session Information
   *
   * The response includes session lifecycle information such as when the session was created, when it expires, and the client context (IP address, page URL, referrer) at session creation time. This information is useful for security auditing and detecting unauthorized access from unusual locations.
   *
   * @param connection
   * @param sessionId Unique identifier of the session to retrieve (UUID format, scoped to authenticated member).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_member_sessions table by session ID UUID. Validate that the session belongs to the currently authenticated member (hrm_member_id matches the authenticated user's ID). Return session details excluding sensitive token fields (access_token, refresh_token). If session not found or does not belong to authenticated member, return 404 Not Found. Include created_at and expired_at timestamps in ISO 8601 format.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":sessionId")
  public async at(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("sessionId")
    sessionId: string & tags.Format<"uuid">,
  ): Promise<IHrmMemberSession> {
    try {
      return await getHrmMemberMemberSessionsSessionId({
        member,
        sessionId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Terminate a specific member session by ID.
   *
   * This operation allows authenticated members to terminate individual sessions, effectively logging out from a specific device or browser. This is useful for security scenarios where a user wants to revoke access from a particular session while maintaining other active sessions.
   *
   * ## Session Termination
   *
   * When a session is terminated, the JWT tokens associated with that session become invalid immediately. The session record is permanently deleted from the system.
   *
   * ## Security Considerations
   *
   * Members can only terminate their own sessions. Attempting to terminate another member's session results in an authorization error. The current session cannot be terminated through this endpoint; use the logout endpoint instead.
   *
   * ## Error Handling
   *
   * - 404: Session not found or already expired
   * - 403: Not authorized to terminate this session (not the session owner)
   *
   * @param connection
   * @param sessionId Unique identifier of the session to terminate (UUID format).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1. Extract sessionId from path parameter and validate UUID format.
   * 2. Verify the authenticated member owns this session by checking hrm_member_id matches the current user's ID.
   * 3. Query hrm_member_sessions table for the session record with the given id.
   * 4. If session not found or already expired, return 404 Not Found.
   * 5. If session belongs to another member, return 403 Forbidden.
   * 6. Delete the session record from hrm_member_sessions table.
   * 7. Return 204 No Content on successful deletion.
   *
   * Edge cases:
   * - Session already expired: Return 404
   * - Session belongs to different member: Return 403
   * - Invalid UUID format: Return 400 Bad Request
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":sessionId")
  public async erase(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("sessionId")
    sessionId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteHrmMemberMemberSessionsSessionId({
        member,
        sessionId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

