@Controller("/hrm/guest/guest/sessions")
export class HrmGuestGuestSessionsController {
  /**
   * Retrieve a paginated list of guest session records with filtering and sorting capabilities.
   *
   * This endpoint allows querying guest session records based on various criteria including device fingerprint, IP address, date ranges, and session expiration status. Each session record contains metadata about the guest device, access location, and session lifecycle timestamps.
   *
   * Guest sessions are temporary authentication tokens created when unauthenticated users access the system. Sessions expire automatically based on the expired_at timestamp and are automatically invalidated beyond that point.
   *
   * **Filtering Options**
   *
   * Search criteria can include device fingerprint matching, IP address filtering, creation date ranges, and expiration status. Results are paginated with cursor-based navigation for large result sets.
   *
   * **Security Considerations**
   *
   * Session records contain sensitive access metadata including IP addresses and referrer URLs. Access to this endpoint should be restricted to authorized administrators or system processes only.
   *
   * @param connection
   * @param body Search criteria for filtering guest session records including device fingerprint, IP address, date ranges, expiration status, and pagination parameters.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Query hrm_guest_sessions table with optional filtering and pagination.
   *
   * **Query Logic**
   *
   * 1. Apply filters from request body:
   *    - device_fingerprint: exact match on hrm_guest.device_fingerprint (join with hrm_guests)
   *    - ip: exact match or prefix matching
   *    - created_at_from / created_at_to: timestamp range filtering
   *    - expired_at_from / expired_at_to: expiration date range filtering
   *    - is_expired: boolean filter comparing expired_at with current timestamp
   *
   * 2. Apply sorting (default: created_at DESC)
   *    - Sort by created_at, expired_at, or ip
   *    - Support ascending and descending order
   *
   * 3. Apply pagination:
   *    - Use cursor-based pagination with created_at and id as composite cursor
   *    - pageSize: 10-100 (default 20)
   *    - Return next cursor for pagination continuation
   *
   * 4. Join with hrm_guests table to access device_fingerprint field
   *
   * **Edge Cases**
   *
   * - Empty result set: return empty array with pagination metadata
   * - Invalid date ranges: return 400 Bad Request
   * - Cursor from expired session: handle gracefully, return next valid results
   *
   * **Performance Considerations**
   *
   * - Use indexes on (hrm_guest_id, created_at) for efficient joins
   * - Consider adding index on (created_at, expired_at) for range queries
   * - Limit maximum pageSize to prevent excessive memory usage
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @GuestAuth()
    guest: GuestPayload,
    @TypedBody()
    body: IHrmGuestSession.IRequest,
  ): Promise<IPageIHrmGuestSession.ISummary> {
    try {
      return await patchHrmGuestGuestSessions({
        guest,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a specific guest session record by its unique identifier.
   *
   * This endpoint returns detailed information about a guest session including the originating IP address, entry URL, referrer, creation timestamp, and expiration time. The session is associated with a guest device identified by its fingerprint.
   *
   * **Authentication**
   *
   * This endpoint does not require authentication as guest sessions are created for unauthenticated users. The session ID serves as the access token.
   *
   * **Error Handling**
   *
   * Returns 404 if the session ID does not exist or has been deleted. Returns 410 if the session has expired beyond its expired_at timestamp.
   *
   * @param connection
   * @param sessionId The unique identifier of the guest session to retrieve (UUID format, global scope).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Query the hrm_guest_sessions table by id parameter using UUID comparison. Join with hrm_guests table to include guest device fingerprint if needed for response. Validate that the session exists and has not been soft-deleted (hrm_guests.deleted_at IS NULL). Check session expiration by comparing current time with expired_at field. Return 404 Not Found if session does not exist or guest is deleted. Return 410 Gone if session has expired. Select fields: id, hrm_guest_id, ip, href, referrer, created_at, expired_at.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":sessionId")
  public async at(
    @GuestAuth()
    guest: GuestPayload,
    @TypedParam("sessionId")
    sessionId: string & tags.Format<"uuid">,
  ): Promise<IHrmGuestSession> {
    try {
      return await getHrmGuestGuestSessionsSessionId({
        guest,
        sessionId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

