@Controller("/hrm/member/organizations")
export class HrmMemberOrganizationsController {
  /**
   * Retrieve a paginated list of organizations the current user belongs to with optional filtering and search capabilities.
   *
   * This endpoint returns organizations accessible to the authenticated user, respecting multi-tenancy data isolation. Users can filter by organization name, search across organization attributes, and paginate through results. The response includes summary information optimized for list displays.
   *
   * **Multi-Tenancy Context**: Results are scoped to organizations where the current user has membership. Users cannot access organizations they do not belong to.
   *
   * **Pagination**: Cursor-based pagination supports large result sets with configurable page size.
   *
   * @param connection
   * @param body Search and filter criteria including name search string, pagination parameters (cursor, limit), and optional filters for active status.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_organizations table filtered by user's organization memberships from hrm_employees or hrm_organization_owners tables.
   *
   * Apply search filters on name (case-insensitive partial match) and description fields. Support status filtering based on deleted_at null check (active vs soft-deleted).
   *
   * Implement cursor-based pagination using created_at or id as cursor field. Validate page size constraints (default 20, max 100).
   *
   * Join with hrm_employees or hrm_organization_owners to filter organizations where current user has membership. Enforce organization-level data isolation.
   *
   * Return IHrmOrganization.ISummary fields: id, name, description, logo_image_url, currency, timezone, fiscal_start_month, created_at.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IHrmOrganization.IRequest,
  ): Promise<IPageIHrmOrganization.ISummary> {
    try {
      return await patchHrmMemberOrganizations({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a specific organization's configuration details by its unique identifier.
   *
   * This endpoint returns the complete organization profile including display name, description, branding assets, and operational settings such as currency, timezone, and fiscal period configuration.
   *
   * **Access Control**
   * The requesting user must be a member of the requested organization. Members cannot access organization details from organizations they do not belong to, ensuring data isolation across the multi-tenant platform.
   *
   * **Organization Context**
   * While the endpoint accepts an explicit organizationId parameter, the user's active organization context (established at login or via switch operation) determines the authorization scope. The system validates that the user belongs to the requested organization before returning data.
   *
   * **Soft Delete Behavior**
   * Organizations marked for deletion (deleted_at is set) are not accessible through this endpoint. The system treats soft-deleted organizations as non-existent for API consumers.
   *
   * @param connection
   * @param organizationId Unique identifier of the organization (UUID format).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Implement organization detail retrieval with the following logic:
   *
   * 1. **Authorization Check**: Verify the authenticated user belongs to the requested organization by querying hrm_employees table with user_id and organization_id. Return 403 Forbidden if no membership exists.
   *
   * 2. **Organization Lookup**: Query hrm_organizations table by id (UUID). Return 404 Not Found if:
   *    - No organization exists with the given id
   *    - Organization has deleted_at set (soft-deleted)
   *
   * 3. **Response Construction**: Return full organization entity including all fields: id, name, description, logo_image_url, currency, timezone, fiscal_start_month, created_at, updated_at.
   *
   * 4. **Error Handling**:
   *    - 401 Unauthorized: Missing or invalid JWT token
   *    - 403 Forbidden: User is not a member of the requested organization
   *    - 404 Not Found: Organization does not exist or is soft-deleted
   *
   * 5. **Performance**: Add database index on hrm_organizations(id) for primary key lookup. Consider caching organization metadata for frequently accessed organizations.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":organizationId")
  public async at(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("organizationId")
    organizationId: string & tags.Format<"uuid">,
  ): Promise<IHrmOrganization> {
    try {
      return await getHrmMemberOrganizationsOrganizationId({
        member,
        organizationId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update organization settings and configuration.
   *
   * This operation allows organization owners to modify their organization's display information, financial settings, and regional preferences. Updates include the organization name, description, logo image, currency code, timezone, and fiscal year start month.
   *
   * **Authorization**
   * Only organization owners can update organization settings. Regular employees and managers cannot modify organization configuration.
