import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IHrmTask } from "../../../../../../api/structures/IHrmTask";
import { IPageIHrmTask } from "../../../../../../api/structures/IPageIHrmTask";
import { MemberAuth } from "../../../../../../decorators/MemberAuth";
import { MemberPayload } from "../../../../../../decorators/payload/MemberPayload";
import { deleteHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskId } from "../../../../../../providers/deleteHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskId";
import { getHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskId } from "../../../../../../providers/getHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskId";
import { patchHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasks } from "../../../../../../providers/patchHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasks";
import { postHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasks } from "../../../../../../providers/postHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasks";
import { putHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskId } from "../../../../../../providers/putHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskId";
import { putHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskIdStatus } from "../../../../../../providers/putHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskIdStatus";

@Controller(
  "/hrm/member/organizations/:organizationId/projects/:projectId/tasks",
)
export class HrmMemberOrganizationsProjectsTasksController {
  /**
   * Create a new task within a specific project.
   *
   * This operation creates a task resource in the specified project. The task can be assigned to an employee who is a member of the project, or left unassigned for later assignment. Tasks support one-level parent-child nesting for subtask organization.
   *
   * **Access Control**
   *
   * Only users with appropriate permissions can create tasks:
   * - Project leads (role: project-lead) in the target project
   * - Users with project:manage permission in the organization
   * - Regular project members cannot create tasks unless they have elevated permissions
   *
   * **Validation Rules**
   *
   * - The target project must exist and belong to the specified organization
   * - The project must be in 'active' status (archived/completed projects cannot receive new tasks)
   * - If assigned_employee_id is provided, the employee must be a member of the project
   * - If parent_task_id is provided, the parent task must belong to the same project
   * - Title is required and must be non-empty
   * - Priority must be one of: low, medium, high, urgent
   * - Status defaults to 'open' if not specified
   *
   * **Response**
   *
   * Returns the complete task object with system-generated fields (id, created_at, updated_at).
   *
   * @param connection
   * @param organizationId Unique identifier of the organization containing the project (global scope).
   * @param projectId Unique identifier of the project to create the task in (scoped to organization).
   * @param body Task creation data including title, description, priority, assignment, and optional parent task reference.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1. Validate organization exists and user has access to it
   * 2. Validate project exists, belongs to the organization, and status is 'active'
   * 3. Validate user has permission to create tasks (project-lead role or project:manage permission)
   * 4. If assigned_employee_id provided: validate employee exists, belongs to organization, and is a member of the project
   * 5. If parent_task_id provided: validate parent task exists and belongs to the same project
   * 6. Insert new task record with:
   *    - project_id from path parameter
   *    - title, description, priority, estimated_hours, due_date from request body
   *    - assigned_employee_id, parent_task_id from request body (nullable)
   *    - status defaults to 'open' if not provided
   *    - created_at, updated_at set to current timestamp
   * 7. Return the created task object with all fields including system-generated id and timestamps
   * 8. Return 404 if project not found
   * 9. Return 403 if user lacks permission
   * 10. Return 400 for validation errors (invalid employee, invalid parent task, invalid priority/status values)
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("organizationId")
    organizationId: string & tags.Format<"uuid">,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IHrmTask.ICreate,
  ): Promise<IHrmTask> {
    try {
      return await postHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasks(
        {
          member,
          organizationId,
          projectId,
          body,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a paginated list of tasks within a specific project with optional filtering and sorting.
   *
   * This endpoint returns tasks belonging to the specified project, supporting filtering by status, priority, assigned employee, and date ranges. Results are paginated for efficient browsing of large task lists.
   *
   * **Filtering Capabilities**
   *
   * - Status filtering: Filter tasks by workflow state (open, in-progress, completed, closed)
   * - Priority filtering: Filter by priority level (low, medium, high, urgent)
   * - Assignment filtering: Filter by assigned employee or unassigned tasks
   * - Date range filtering: Filter by due date or creation date ranges
   * - Text search: Search by task title or description
   *
   * **Pagination**
   *
   * Results are returned with cursor-based pagination support. Include page number and page size in the request to control result set size. The response includes pagination metadata for navigation.
   *
   * **Security**
   *
   * Access is restricted to organization members with project membership. Project leads and users with project:manage permission have full access. Regular members can view tasks they are assigned to or all tasks based on organization settings.
   *
   * @param connection
   * @param organizationId Unique identifier of the organization (global scope)
   * @param projectId Unique identifier of the project within the organization
   * @param body Search criteria for filtering tasks including status, priority, assignment, date ranges, text search, and pagination parameters.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_tasks table filtered by project_id.
   *
   * **Implementation Steps**
   *
   * 1. Validate organizationId and projectId exist and belong together (project.hrm_organization_id matches organizationId)
   * 2. Verify user has access to the organization and project (check hrm_project_members or project:manage permission)
   * 3. Apply search filters from request body:
   *    - status: IN clause on tasks.status
   *    - priority: IN clause on tasks.priority
   *    - assigned_employee_id: equals or IS NULL for unassigned
   *    - due_date_from/due_date_to: range query on tasks.due_date
   *    - created_from/created_to: range query on tasks.created_at
   *    - search: LIKE query on title and description using trigram index
   * 4. Apply pagination: offset and limit based on page and pageSize
   * 5. Apply sorting: default by created_at DESC, support custom sort fields
   * 6. Join with hrm_employees for assigned_employee details if requested
   * 7. Return paginated result with IPageIHrmTask.ISummary type
   *
   * **Edge Cases**
   *
   * - Empty result set: return page with empty items array and totalItems=0
   * - Invalid filters: ignore invalid filter values, do not return error
   * - Project not found: return 404 Not Found
   * - No access: return 403 Forbidden
   * - Soft-deleted tasks: exclude tasks where deleted_at IS NOT NULL
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("organizationId")
    organizationId: string & tags.Format<"uuid">,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IHrmTask.IRequest,
  ): Promise<IPageIHrmTask.ISummary> {
    try {
      return await patchHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasks(
        {
          member,
          organizationId,
          projectId,
          body,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed information for a specific task within a project.
   *
   * This endpoint returns the complete task entity including its title, description, status, priority, time estimates, due date, and assignment information. The task must belong to the specified project, and the project must belong to the specified organization.
   *
   * **Access Control**
   *
   * Only employees who are members of the project can access task details. Project leads have full task management permissions, while regular members can view task details. Employees not assigned to the project cannot access tasks in that project (Section 126).
   *
   * **Task Hierarchy**
   *
   * Tasks support one-level parent-child nesting for subtasks. The response includes parent_task_id if this task is a subtask, and the parent task's information can be retrieved separately.
   *
   * **Status Workflow**
   *
   * Tasks progress through states: open → in-progress → completed → closed. Status changes are logged in hrm_task_histories for audit purposes.
   *
   * @param connection
   * @param organizationId Unique identifier of the organization containing the project and task (global scope).
   * @param projectId Unique identifier of the project containing the task (global scope).
   * @param taskId Unique identifier of the task to retrieve (global scope).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_tasks table by taskId, project_id, and verify organization context through project relationship. Join with hrm_projects to validate organization_id matches the path parameter. Check project membership to ensure the requesting employee belongs to the project (Section 126). Include assigned employee details via join with hrm_employees. Verify task is not soft-deleted (deleted_at IS NULL). Return 404 if task not found or access denied.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":taskId")
  public async at(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("organizationId")
    organizationId: string & tags.Format<"uuid">,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedParam("taskId")
    taskId: string & tags.Format<"uuid">,
  ): Promise<IHrmTask> {
    try {
      return await getHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskId(
        {
          member,
          organizationId,
          projectId,
          taskId,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update task details including title, description, status, priority, estimated hours, due date, and assigned employee.
   *
   * This operation allows project leads and users with project management permissions to modify task properties within their assigned project. When the task status changes, a history record is automatically created for audit purposes.
   *
   * **Permission Requirements**
   *
   * - Project lead role in the project, OR
   * - User with project:manage permission in the organization
   *
   * **Status Transitions**
   *
   * Tasks progress through states: open → in-progress → completed → closed. Invalid status transitions are rejected.
   *
   * **Assignment Rules**
   *
   * - Assigned employee must be a member of the same organization
   * - Parent task (if set) must belong to the same project
   * - Circular parent-child references are prevented
   *
   * @param connection
   * @param organizationId UUID of the organization containing the project and task (global scope)
   * @param projectId UUID of the project containing the task (scoped to organization)
   * @param taskId UUID of the task to update (scoped to project)
   * @param body Task fields to update. Only provided fields will be modified; omitted fields retain their current values.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1. Validate organization exists and user has access. 2. Validate project belongs to organization and user has project access. 3. Validate task exists and belongs to project. 4. Check permission: user must be project-lead of this project OR have project:manage permission. 5. Validate assigned_employee_id if provided: employee must belong to same organization. 6. Validate parent_task_id if provided: parent task must belong to same project. 7. Validate status transitions are valid (open→in-progress→completed→closed). 8. If status changes, create hrm_task_history record with old status, new status, timestamp, and user_id. 9. Update task fields (title, description, status, priority, estimated_hours, due_date, assigned_employee_id, parent_task_id). 10. Return updated task with all fields including assigned employee and parent task details.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":taskId")
  public async update(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("organizationId")
    organizationId: string & tags.Format<"uuid">,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedParam("taskId")
    taskId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IHrmTask.IUpdate,
  ): Promise<IHrmTask> {
    try {
      return await putHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskId(
        {
          member,
          organizationId,
          projectId,
          taskId,
          body,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Permanently removes a task from a project within an organization using soft deletion.
   *
   * This operation marks the task as deleted by setting its deleted_at timestamp, preserving the record for audit purposes while removing it from active task lists. The task must belong to the specified project and organization for data isolation.
   *
   * **Deletion Behavior**
   *
   * Soft deletion preserves the task record and all associated task history entries. The task becomes invisible in normal queries but remains in the database for compliance and audit trails. Child tasks (subtasks) are also soft deleted when the parent task is deleted.
   *
   * **Validation Constraints**
   *
   * The system validates that the authenticated user has project management permissions before allowing task deletion. The task must exist and belong to the specified project and organization. Organization and project context must match the path parameters for multi-tenancy data isolation.
   *
   * @param connection
   * @param organizationId UUID identifier of the organization that owns the project containing this task (global scope).
   * @param projectId UUID identifier of the project containing this task (scoped to organization).
   * @param taskId UUID identifier of the task to delete (scoped to project).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1. Validate organization exists and user has access permission.
   * 2. Validate project exists within the organization and user has project:manage permission.
   * 3. Validate task exists within the project.
   * 4. Verify task's project_id matches the projectId path parameter.
   * 5. Verify project's hrm_organization_id matches the organizationId path parameter.
   * 6. Set deleted_at to current timestamp (soft delete).
   * 7. Cascade soft delete to all child tasks (recursive deletion of subtasks).
   * 8. Return 200 OK with null response body.
   *
   * Edge cases:
   * - Task not found: Return 404 Not Found
   * - Permission denied: Return 403 Forbidden
   * - Organization/project mismatch: Return 404 Not Found (do not reveal existence)
   * - User lacks project:manage permission: Return 403 Forbidden
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":taskId")
  public async erase(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("organizationId")
    organizationId: string & tags.Format<"uuid">,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedParam("taskId")
    taskId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskId(
        {
          member,
          organizationId,
          projectId,
          taskId,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update the workflow status of a task within a project.
   *
   * This operation changes the task's status to a new value and automatically records the status transition in the task history audit trail. The system captures the previous status, new status, timestamp, and the member who made the change.
   *
   * **Status Values**
   *
   * Allowed status values are: open, in-progress, completed, closed. The status field tracks the task's progress through its workflow lifecycle.
   *
   * **Permissions**
   *
   * Only project leads, users with project management permission, or the assigned employee (for their own tasks) can update task status. Users without appropriate permissions will receive an authorization error.
   *
   * **Audit Trail**
   *
   * Every status change is recorded in the task history table for compliance and debugging purposes. The history record includes the old status, new status, exact timestamp, and the member ID of the user who made the change.
   *
   * @param connection
   * @param organizationId UUID of the organization containing the project and task (global scope)
   * @param projectId UUID of the project containing the task (scoped to organization)
   * @param taskId UUID of the task to update status (scoped to project)
   * @param body New status value for the task. Must be one of: open, in-progress, completed, closed.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1. Validate organization, project, and task exist and belong to the correct hierarchy.
   * 2. Verify the authenticated member has permission to update this task (project lead, project:manage permission, or assigned employee).
   * 3. Validate the new status value is one of: open, in-progress, completed, closed.
   * 4. Fetch the current task status from hrm_tasks table.
   * 5. Update the task status in hrm_tasks table.
   * 6. Insert a new record into hrm_task_histories with: hrm_task_id, hrm_member_id (current user), timestamp (now), old_status (previous value), new_status (requested value).
   * 7. Return the updated task object.
   *
   * Edge cases:
   * - Task not found: Return 404
   * - Invalid status value: Return 400 with validation error
   * - Permission denied: Return 403
   * - Task already in requested status: Still record history but update timestamp
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":taskId/status")
  public async status(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("organizationId")
    organizationId: string & tags.Format<"uuid">,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedParam("taskId")
    taskId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IHrmTask.IStatusUpdate,
  ): Promise<IHrmTask> {
    try {
      return await putHrmMemberOrganizationsOrganizationIdProjectsProjectIdTasksTaskIdStatus(
        {
          member,
          organizationId,
          projectId,
          taskId,
          body,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

import { TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IPageIHrmTaskHistory } from "../../../../../../../api/structures/IPageIHrmTaskHistory";
import { MemberAuth } from "../../../../../../../decorators/MemberAuth";
